@RestController
@RequestMapping("/api/v1/$PATH$")
@RequiredArgsConstructor
public class $NAME$ {

    private final Service service;

    @GetMapping
    public ResponseEntity<List<DtoResponse>> findAll() {
        return ResponseEntity.ok(service.findAll());
    }

    @GetMapping("/{id}")
    public ResponseEntity<DtoResponse> findById(@PathVariable Long id) {
        return ResponseEntity.ok(service.findById(id));
    }

    @PostMapping
    public ResponseEntity<DtoResponse> create(
            @Valid @RequestBody DtoRequest request) {

        return ResponseEntity
                .status(HttpStatus.CREATED)
                .body(service.save(request));
    }

    @PutMapping("/{id}")
    public ResponseEntity<DtoResponse> update(
            @PathVariable Long id,
            @Valid @RequestBody DtoRequest request) {

        return ResponseEntity.ok(service.update(id, request));
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(@PathVariable Long id) {
        service.delete(id);
        return ResponseEntity.noContent().build();
    }
}

@RestController
@RequestMapping("/api/v1/$PATH$")
@RequiredArgsConstructor
public class $NAME$ {

    private final Service service;
}

@Service
@RequiredArgsConstructor
@Transactional(readOnly = true)
public class $Service$ {

  private final $REPOSITORY$ repository;

  // Buscar un elemento por su id
  public $TYPE$DtoResponse findById(Long id) {
    return toResponse(getById(id));
  }

  // Recuperar todos los elementos
  public List<$TYPE$DtoResponse> findAll() {
    return repository.findAll()
      .stream()
      .map(this::toResponse)
      .toList();
  }

  // Crear un elemento
  @Transactional
  public $TYPE$DtoResponse create(DtoRequest request) {
    Entity entity = new Entity();
    // setear campos
    entity.setName(request.name());

    return toResponse(repository.save(entity));
  }

  // Actualizar un elemento por su id
  @Transactional
  public $TYPE$DtoResponse update(Long id, DtoRequest request) {
    // Buscar si existe el elemento a actualizar. Si existe se recupera el Entity
    Entity entity = getById(id);
    // actualizar campos
    entity.setName(request.name());

    return toResponse(repository.save(entity));
  }

  // Eliminar un elemento por su id
  @Transactional
  public void delete(Long id) {
    repository.delete(getById(id));
  }

  // Buscar un elemento por su id
  private Entity getById(Long id) {
    return repository.findById(id)
      .orElseThrow(() ->
        new ResourceNotFoundException("Entity no encontrado: " + id));
  }

  //Mapear Entity a DtoResponse
  private $TYPE$DtoResponse toResponse(Entity entity) {
    return new $TYPE$DtoResponse(
      entity.getId()
    );
  }
}

public interface I$NAME$Service {

  $TYPE$DtoResponse findById(Long id);

  List<$TYPE$DtoResponse> findAll();

  $TYPE$DtoResponse save($TYPE1$DtoRequest request);

  $TYPE$DtoResponse update(Long id, $TYPE1$DtoRequest request);

  void delete(Long id);
}

@Override
public List<DtoResponse> findAll() {
  return repository.findAll()
    .stream()
    .map(this::toResponse)
    .toList();
}

private DtoResponse toResponse(Entity entity) {
  return new DtoResponse(
    entity.getId()
  );
}

@Override
public $TYPE$DtoResponse findById(Long id) {
  Entity entity = repository.findById(id)
      .orElseThrow(() ->
        new ResourceNotFoundException("Elemento no encontrado: " + id));

  return new $TYPE$DtoResponse(
    entity.getId()
  );
}

@Transactional
@Override
public DtoResponse save(DtoRequest request) {
  Entity entity = new Entity();

  // setear campos
  entity.setName(request.name());

  return toResponse(repository.save(entity));
}

@Transactional
public DtoResponse update(Long id, DtoRequest request) {
  Entity entity = repository.findById(id)
    .orElseThrow(() ->
      new ResourceNotFoundException("Elemento no encontrado: " + id));

  // actualizar campos
  entity.setName(request.name());

  return toResponse(repository.save(entity));
}

@Transactional
@Override
public void delete(Long id) {
  $TYPE$Entity entity = repository.findById(id)
    .orElseThrow(() ->
      new ResourceNotFoundException("Elemento no encontrado: " + id));

  repository.delete(entity);
}

private $TYPEDto$Response toResponse($TYPE$Entity entity) {
    return new $TYPEDto$Response(
            entity.getId(),
            entity.getName(),
            entity.getEmail()
    );
}

@Id
@GeneratedValue(strategy = GenerationType.IDENTITY)
private Long id;

// Texto
@Column(nullable = false, length = 100)
private String name;

// Texto largo
@Column(columnDefinition = "TEXT")
private String description;

// Números enteros
private Integer quantity;

private Long externalId;

// Decimal / dinero
@Column(precision = 19, scale = 2)
private BigDecimal amount;

// Boolean
@Column(nullable = false)
private Boolean active;

// Enumeración - Uso de ENUM
@Enumerated(EnumType.STRING)
@Column(nullable = false, length = 30)
private Status status;

// Fecha y hora
private LocalDateTime dateTime;

// Solo fecha
private LocalDate date;

// Solo hora
private LocalTime time;

// UUID
@Column(nullable = false, unique = true)
private UUID uuid;

// Auditoría
@CreationTimestamp
@Column(nullable = false, updatable = false)
private LocalDateTime createdAt;

@UpdateTimestamp
@Column(nullable = false)
private LocalDateTime updatedAt;

